Lemma sec_not_live_after : forall L st cs (p : aptr) mb ms n s,
  asec_wf L st cs -> Permutation cs (sec_chunks_of st) ->
  (a_live st) !! p = Some (CSec mb ms n) -> a_live s = delete p (a_live st) ->
  ~ sec_live s (CSec mb ms n).
Proof.
